package com.google.gson.internal.bind;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.*;
import java.io.IOException;
import java.io.Reader;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class JsonTreeReader_skipValue_TriageGen0Test {

    private JsonElement element;
    private JsonTreeReader reader;

    @Before
    public void setup() {
        element = new JsonElement();
        reader = new JsonTreeReader(element);
    }

    @Test
    public void testSkipValue_NonNameToken() throws IOException {
        // Arrange
        reader.stackSize = 1;
        reader.pathNames = new String[]{null};
        reader.pathIndices = new int[]{0};

        // Act
        reader.skipValue();

        // Assert
        assertEquals("null", reader.pathNames[reader.stackSize - 1]);
        assertEquals(1, reader.pathIndices[reader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_NameToken() throws IOException {
        // Arrange
        reader.stackSize = 2;
        reader.pathNames = new String[]{null, null};
        reader.pathIndices = new int[]{0, 0};
        reader.peek = () -> JsonToken.NAME;

        // Act
        reader.skipValue();

        // Assert
        assertEquals("null", reader.pathNames[reader.stackSize - 2]);
        assertEquals(1, reader.pathIndices[reader.stackSize - 2]);
    }

    @Test
    public void testSkipValue_NullPathName() throws IOException {
        // Arrange
        reader.stackSize = 1;
        reader.pathNames = new String[]{"null"};
        reader.pathIndices = new int[]{0};

        // Act
        reader.skipValue();

        // Assert
        assertEquals("null", reader.pathNames[reader.stackSize - 1]);
        assertEquals(1, reader.pathIndices[reader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_NullPathIndices() throws IOException {
        // Arrange
        reader.stackSize = 1;
        reader.pathNames = new String[]{null};
        reader.pathIndices = new int[]{0};

        // Act
        reader.skipValue();

        // Assert
        assertEquals("null", reader.pathNames[reader.stackSize - 1]);
        assertEquals(1, reader.pathIndices[reader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_EmptyPathNames() throws IOException {
        // Arrange
        reader.stackSize = 1;
        reader.pathNames = new String[]{null};
        reader.pathIndices = new int[]{0};

        // Act
        reader.skipValue();

        // Assert
        assertEquals("null", reader.pathNames[reader.stackSize - 1]);
        assertEquals(1, reader.pathIndices[reader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_NullPeek() throws IOException {
        // Arrange
        reader.stackSize = 1;
        reader.pathNames = new String[]{null};
        reader.pathIndices = new int[]{0};
        reader.peek = () -> null;

        // Act and Assert
        assertThrows(IOException.class, () -> reader.skipValue());
    }

    @Test
    public void testSkipValue_NullPeekValue() throws IOException {
        // Arrange
        reader.stackSize = 1;
        reader.pathNames = new String[]{null};
        reader.pathIndices = new int[]{0};
        reader.peek = () -> JsonToken.NAME;

        // Act
        reader.skipValue();

        // Assert
        assertEquals("null", reader.pathNames[reader.stackSize - 1]);
        assertEquals(1, reader.pathIndices[reader.stackSize - 1]);
    }
}
